const p = $json.body ?? $json;
const fail = (status, message) => { throw new Error(`${status}:${message}`); };
if (!p || p.schemaVersion !== 1 || typeof p.deliveryId !== 'string' || typeof p.idempotencyKey !== 'string') fail(400, 'malformed payload');
if (!['ALERT_CREATED', 'ALERT_RESOLVED'].includes(p.eventType)) fail(422, 'unsupported event type');
if (!p.stream?.id || !p.stream?.name || !p.stream?.identifier || !p.alert?.id) fail(400, 'missing stream or alert');
if (!['WARNING', 'CRITICAL'].includes(p.alert.severity)) fail(422, 'unsupported severity');
if (p.eventType === 'ALERT_CREATED' && (p.alert.status !== 'ACTIVE' || p.alert.resolvedAt !== null)) fail(422, 'invalid active alert');
if (p.eventType === 'ALERT_RESOLVED' && (p.alert.status !== 'RESOLVED' || typeof p.alert.resolvedAt !== 'string' || Number.isNaN(Date.parse(p.alert.resolvedAt)))) fail(422, 'invalid resolved alert');
return [{ json: { deliveryId: p.deliveryId, idempotencyKey: p.idempotencyKey, eventType: p.eventType, schemaVersion: 1, occurredAt: p.occurredAt, stream: { id: p.stream.id, name: p.stream.name, identifier: p.stream.identifier }, liveSessionId: p.liveSessionId ?? null, alert: { id: p.alert.id, type: p.alert.type, severity: p.alert.severity, status: p.alert.status, description: p.alert.description ?? '', recommendedAction: p.alert.recommendedAction ?? '', firstDetectedAt: p.alert.firstDetectedAt ?? null, lastDetectedAt: p.alert.lastDetectedAt ?? null, resolvedAt: p.alert.resolvedAt ?? null } } }];

const p = $('Validate and Minimize').first().json;
const critical = p.alert.severity === 'CRITICAL';
const resolved = p.eventType === 'ALERT_RESOLVED';
const title = resolved ? 'LiveWarden Alert Resolved' : (critical ? 'LiveWarden Critical Alert' : 'LiveWarden Warning');
const label = resolved ? '**RESOLVED**' : (critical ? '**CRITICAL**\n**ACTION REQUIRED**' : '**WARNING**');
const color = resolved ? 5763719 : (critical ? 15158332 : 16753920);
const fields = [
  { name: 'Stream', value: `${p.stream.name} (\`@${p.stream.identifier}\`)`, inline: true },
  { name: 'Alert', value: p.alert.type, inline: true },
  { name: 'Status', value: resolved ? 'RESOLVED' : p.alert.status, inline: true },
  { name: 'Description', value: p.alert.description || 'No description', inline: false },
  { name: 'Recommended Action', value: p.alert.recommendedAction || 'None', inline: false },
  { name: 'First Detected', value: p.alert.firstDetectedAt || 'Unavailable', inline: true },
  { name: resolved ? 'Resolved At' : 'Last Detected', value: resolved ? p.alert.resolvedAt : (p.alert.lastDetectedAt || 'Unavailable'), inline: true },
  ...(p.liveSessionId ? [{ name: 'Session', value: p.liveSessionId, inline: false }] : []),
  { name: 'Alert ID', value: p.alert.id.slice(0, 8), inline: true }
];
return [{ json: { username: 'LiveWarden', embeds: [{ title, description: label, color, fields, timestamp: p.occurredAt || new Date().toISOString(), footer: { text: 'LiveWarden' } }] } }];
